const Hub = (() => {
  let data = { profile:{}, tasks:[], timetable:[], subjects:[], quick_links:[], flashcards:[], flashcard_sets:[] };
  let flashcardIndex=0, flashcardFlipped=false, flashcardDeck='all';
  const boards=['AQA','OCR','Pearson Edexcel','CCEA','WJEC / Eduqas','Cambridge International','IB','Other'];
  function normaliseCourse(s){ if(typeof s==='string') return {name:s, exam_board:'', specification:'', course:'', progress:0}; return {name:String(s?.name||'').trim(),exam_board:String(s?.exam_board||s?.examBoard||'').trim(),specification:String(s?.specification||s?.spec_link||'').trim(),course:String(s?.course||'').trim(),progress:Math.max(0,Math.min(100,Number(s?.progress)||0))}; }
  function courseList(){ data.subjects=(data.subjects||[]).map(normaliseCourse).filter(s=>s.name); return data.subjects; }
  let taskFilter = 'all';
  const $ = s => document.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const auth = (url, opts={}) => fetch(url, { ...opts, credentials:'same-origin', cache:'no-store', headers:{'Content-Type':'application/json',...(opts.headers||{})} });
  const toast = msg => { const el=$('#toast'); el.textContent=msg; el.classList.add('show'); clearTimeout(window._toast); window._toast=setTimeout(()=>el.classList.remove('show'),2400); };
  const formatDate = d => { if(!d) return 'No date'; const x=new Date(d+'T12:00:00'); if(isNaN(x)) return d; const diff=Math.round((new Date(d+'T00:00:00')-new Date(todayISO+'T00:00:00'))/864e5); return diff===0?'Today':diff===1?'Tomorrow':diff===-1?'Yesterday':x.toLocaleDateString('en-GB',{day:'numeric',month:'short'}); };
  let today, dayName, todayISO;
  const refreshToday=()=>{today=new Date();dayName=today.toLocaleDateString('en-GB',{weekday:'long'});todayISO=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');};
  refreshToday();

  async function load(){ try { const r=await auth('/api/student'); if(r.status===401){if(typeof showLogin==='function')showLogin('Your session expired. Please sign in again.');return;} if(!r.ok) throw new Error('Could not load your hub.'); const j=await r.json(); data=j.student||data; renderAll(); } catch(e){toast(e.message||'Could not load your hub.');} }
  async function save(){ try { const r=await auth('/api/student',{method:'PUT',body:JSON.stringify(data)}); if(!r.ok){toast('Could not save changes');return false;} data=(await r.json()).student; return true; } catch(e){toast('Could not save changes');return false;} }
  function renderProfile(){
    const p=data.profile||{}; const name=p.display_name||p.username||'Student';
    $('#sidebarName').textContent=name; $('#sidebarUsername').textContent='@'+(p.username||'student'); $('#avatarInitial').textContent=name.charAt(0).toUpperCase();
    $('#welcomeTitle').textContent=`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${name.split(' ')[0]}.`;
    $('#welcomeSub').textContent=p.year_group ? `${p.year_group}${p.school?' · '+p.school:''} · ${dayName}` : `It’s ${dayName}. Add your year group in Settings to personalise this message.`;
    $('#pageTitle').textContent=`${dayName}`; $('#todayLabel').textContent=today.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
    renderCourseEditor(); renderQuickLinkEditor();
  }
  function renderStats(){
    const open=(data.tasks||[]).filter(t=>!t.done); $('#statTasks').textContent=open.length; $('#taskBadge').textContent=open.length;
    $('#statTasksSub').textContent=open.length?(open.filter(t=>t.due===todayISO).length+' due today'): 'All caught up';
    const lessons=(data.timetable||[]).filter(t=>t.day===dayName.toLowerCase()); $('#statLessons').textContent=lessons.length; $('#statLessonsSub').textContent=lessons.length?'On today’s schedule':'No lessons added';
    $('#statSubjects').textContent=(data.subjects||[]).length; $('#statFocus').textContent=open.length?'25 min':'Ready';
  }
  function renderHome(){
    const lessons=(data.timetable||[]).filter(t=>t.day===dayName.toLowerCase()).sort((a,b)=>(a.start||'').localeCompare(b.start||''));
    $('#homeTimetable').innerHTML=lessons.length?lessons.slice(0,5).map(t=>`<div class="compact-row"><span class="time">${esc(t.start||'—')}</span><div><strong>${esc(t.subject||'Lesson')}</strong><small>${esc(t.room||'')}</small></div></div>`).join(''):'<div class="empty">No lessons for today. Add your timetable in the Timetable page.</div>';
    const tasks=(data.tasks||[]).filter(t=>!t.done).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5);
    $('#homeTasks').innerHTML=tasks.length?tasks.map(t=>`<div class="compact-row"><span class="priority ${esc(t.priority)}"></span><div><strong>${esc(t.title)}</strong><small>${esc(t.subject)} · ${formatDate(t.due)}</small></div></div>`).join(''):'<div class="empty">No open tasks. Nice.</div>';
    $('#quickLinks').innerHTML=(data.quick_links||[]).map(l=>`<a class="quick-link" href="${esc(l.url)}" target="_blank" rel="noopener"><span>${esc(l.icon||'↗')}</span><div><strong>${esc(l.title)}</strong><small>Open ↗</small></div></a>`).join('') || '<div class="empty">Add your school links in Settings.</div>';
  }
  function renderTimetable(){
    const days=['monday','tuesday','wednesday','thursday','friday']; const labels=['Monday','Tuesday','Wednesday','Thursday','Friday'];
    $('#timetableList').innerHTML=labels.map((d,i)=>{const rows=(data.timetable||[]).filter(t=>t.day===days[i]).sort((a,b)=>(a.start||'').localeCompare(b.start||'')); return `<div class="day-card glass ${days[i]===dayName.toLowerCase()?'today':''}"><div class="day-head"><strong>${d}</strong>${days[i]===dayName.toLowerCase()?'<span>Today</span>':''}</div>${rows.length?rows.map(t=>`<div class="lesson"><time>${esc(t.start||'')}<br>${esc(t.end||'')}</time><div><strong>${esc(t.subject||'Lesson')}</strong><small>${esc(t.room||'')}</small></div><button class="delete-lesson" data-id="${esc(t.id)}">×</button></div>`).join(''):'<div class="day-empty">No lessons</div>'}</div>`;}).join('');
    document.querySelectorAll('.delete-lesson').forEach(b=>b.onclick=async()=>{data.timetable=data.timetable.filter(t=>t.id!==b.dataset.id);await save();renderAll();});
  }
  function renderTasks(){
    let tasks=[...(data.tasks||[])].sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999'));
    tasks=tasks.filter(t=>taskFilter==='all'||(taskFilter==='open'&&!t.done)||(taskFilter==='done'&&t.done)||(taskFilter==='high'&&t.priority==='high'));
    $('#taskList').innerHTML=tasks.length?tasks.map(t=>`<div class="task-row glass ${t.done?'done':''} ${!t.done&&t.due&&t.due<todayISO?'overdue':''}"><button class="check ${t.done?'checked':''}" data-task="${esc(t.id)}">${t.done?'✓':''}</button><div class="task-main"><strong>${esc(t.title)}</strong><div><span>${esc(t.subject)}</span><span>${t.due?formatDate(t.due):'No due date'}</span><span class="priority-label ${esc(t.priority)}">${esc(t.priority)}</span></div></div><button class="delete-task" data-task="${esc(t.id)}">×</button></div>`).join(''):'<div class="empty large-empty">No tasks in this view. Add one when you have something to remember.</div>';
    document.querySelectorAll('.check').forEach(b=>b.onclick=async()=>{const t=data.tasks.find(x=>x.id===b.dataset.task);t.done=!t.done;await save();renderAll();});
    document.querySelectorAll('.delete-task').forEach(b=>b.onclick=async()=>{const r=await auth('/api/student/tasks/'+b.dataset.task,{method:'DELETE'});if(!r.ok){toast('Could not delete task');return;}data.tasks=data.tasks.filter(x=>x.id!==b.dataset.task);renderAll();toast('Task deleted');});
  }
  function renderSubjects(){ const courses=courseList(); $('#subjectGrid').innerHTML=courses.map((s,i)=>{const colour=['mint','blue','purple','orange','pink'][i%5]; const board=s.exam_board||'Exam board not set'; const pct=s.progress||0; return `<article class="subject-card glass ${colour}"><div class="subject-dot"></div><span>${esc(s.exam_board||'Course')}</span><h3>${esc(s.name)}</h3><p>${esc(s.course||'Course not set')} · ${esc(board)}</p><div class="course-progress"><div><span>Course progress</span><strong>${pct}%</strong></div><div class="progress-track"><i style="width:${pct}%"></i></div></div>${s.specification?`<a class="text-button" href="${esc(s.specification)}" target="_blank" rel="noopener">Open specification ↗</a>`:''}<button class="text-button subject-ai" data-subject="${esc(s.name)}">Study ${esc(s.name)} →</button><button class="subject-remove" data-index="${i}">×</button></article>`}).join('') || '<div class="empty large-empty">No courses yet. Add one from Settings.</div>'; document.querySelectorAll('.subject-ai').forEach(b=>b.onclick=()=>{go('assistant'); $('#prompt').value=`Help me revise ${b.dataset.subject}. Start by asking what topic I am studying.`; $('#prompt').focus();}); document.querySelectorAll('.subject-remove').forEach(b=>b.onclick=async()=>{data.subjects.splice(Number(b.dataset.index),1);await save();renderAll();}); }
  function renderCourseEditor(){ const courses=courseList(); const el=$('#courseEditor'); if(!el)return; el.innerHTML=courses.length?courses.map((c,i)=>`<div class="course-editor-row" data-course="${i}"><div class="course-row-main"><label>Subject<input data-field="name" value="${esc(c.name)}" placeholder="e.g. Biology"></label><label>Course / qualification<input data-field="course" value="${esc(c.course)}" placeholder="e.g. GCSE Biology"></label><label>Exam board<select data-field="exam_board"><option value="">Select board</option>${boards.map(b=>`<option ${c.exam_board===b?'selected':''}>${b}</option>`).join('')}</select></label><label>Specification link<input data-field="specification" type="url" value="${esc(c.specification)}" placeholder="https://…"></label></div><div class="course-row-bottom"><label class="progress-field">Course progress <div class="progress-input"><input data-field="progress" type="range" min="0" max="100" step="5" value="${c.progress}"><output>${c.progress}%</output></div></label><button type="button" class="delete-editor" data-course-delete="${i}">Remove</button></div></div>`).join(''):'<div class="empty editor-empty">No courses added yet. Click “Add course” to create your first one.</div>'; el.querySelectorAll('[data-field=progress]').forEach(input=>input.oninput=()=>input.nextElementSibling.value=input.value+'%'); el.querySelectorAll('[data-course-delete]').forEach(b=>b.onclick=()=>{data.subjects.splice(Number(b.dataset.courseDelete),1);renderCourseEditor();renderSubjects();}); }
  function renderQuickLinkEditor(){ const el=$('#quickLinkEditor'); if(!el)return; const links=data.quick_links||[]; el.innerHTML=links.map((l,i)=>`<div class="editor-row"><input data-link="title" data-index="${i}" value="${esc(l.title||'')}" placeholder="Link name"><input data-link="url" data-index="${i}" type="url" value="${esc(l.url||'')}" placeholder="https://example.com"><button type="button" class="delete-editor" data-link-delete="${i}">Remove</button></div>`).join('')||'<div class="empty editor-empty">No quick links yet. Add your school platforms here.</div>'; el.querySelectorAll('[data-link-delete]').forEach(b=>b.onclick=()=>{data.quick_links.splice(Number(b.dataset.linkDelete),1);renderQuickLinkEditor();}); }
  let flashcardStarredOnly=false, flashcardDirection='question', flashcardAutoplay=null, flashcardAutoSeconds=4, flashSpeak=false, studyTicker=null;
  function currentFlashcardBase(){
    let cards=(data.flashcards||[]).filter(c=>flashcardDeck==='all'||(c.deck||'General')===flashcardDeck);
    if(flashcardStarredOnly) cards=cards.filter(c=>c.starred);
    return cards;
  }
  function renderFlashcards(){
    const all=data.flashcards||[];
    const setCards=all.filter(c=>flashcardDeck==='all'||(c.deck||'General')===flashcardDeck);
    const cards=flashcardStarredOnly?setCards.filter(c=>c.starred):setCards;
    const sets=(data.flashcard_sets||[]).filter(x=>x&&x.name);
    const names=sets.map(x=>x.name);
    const filter=$('#flashcardDeckFilter');
    if(filter){filter.innerHTML='<option value="all">All sets</option>'+names.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('');filter.value=names.includes(flashcardDeck)?flashcardDeck:'all';}
    const progress=data.learn_progress||{}, mastered=setCards.filter(c=>Number(progress[c.id]?.mastery||0)>=2).length;
    const due=setCards.filter(c=>{const d=progress[c.id]?.due_at;return !d||new Date(d).getTime()<=Date.now();}).length;
    const selectedSet=sets.find(x=>x.name===flashcardDeck);
    $('#flashcardSetKicker').textContent=flashcardDeck==='all'?'All sets':'Study set';
    $('#flashcardSetTitle').textContent=flashcardDeck==='all'?'Your flashcards':flashcardDeck;
    $('#flashcardSetMeta').textContent=flashcardDeck!=='all'&&selectedSet?.description?selectedSet.description:(setCards.length?`${setCards.length} cards · ${mastered} mastered · ${due} ready to review${flashcardStarredOnly?' · starred only':''}`:'This set is ready for your first cards.');
    $('#setCardCount').textContent=setCards.length; $('#setMastery').textContent=setCards.length?Math.round(mastered/setCards.length*100)+'%':'0%'; $('#setDue').textContent=due;
    $('#flashcardStarredFilter').textContent=flashcardStarredOnly?'★ Starred':'☆ Starred';
    if(!cards.length){const starredEmpty=flashcardStarredOnly&&setCards.length;$('#flashcardStudy').innerHTML=`<div class="flashcard-empty"><div class="empty-card-icon">${starredEmpty?'★':'＋'}</div><strong>${starredEmpty?'No starred cards yet':'This set is empty'}</strong><span>${starredEmpty?'Star cards you want to revisit and they will appear here.':'Import cards or create your first question and answer.'}</span><div class="empty-actions">${starredEmpty?'<button class="primary-button" id="clearStarredFilter">Show all cards</button>':'<button class="primary-button" id="emptyCreateCard">Create card</button><button class="small-button" id="emptyImportCards">Import cards</button>'}</div></div>`;if(starredEmpty)$('#clearStarredFilter').onclick=()=>{flashcardStarredOnly=false;flashcardIndex=0;renderFlashcards();};else{$('#emptyCreateCard').onclick=addFlashcard;$('#emptyImportCards').onclick=importFlashcards;}$('#flashcardList').innerHTML='';return;}
    flashcardIndex=Math.min(flashcardIndex,cards.length-1); const c=cards[flashcardIndex];
    const front=flashcardDirection==='question'?c.question:c.answer, back=flashcardDirection==='question'?c.answer:c.question;
    $('#flashcardStudy').innerHTML=`<div class="flashcard-stage"><div class="study-count">${flashcardIndex+1} / ${cards.length}</div><div class="study-flip-wrap ${flashcardFlipped?'is-flipped':''}" id="studyCard" tabindex="0" role="button" aria-label="${flashcardFlipped?'Hide answer':'Reveal answer'}"><div class="study-face study-front"><div class="flashcard-label">${flashcardDirection==='question'?'Question':'Answer'}</div><div class="flashcard-question">${esc(front)}</div><div class="flip-hint">Click, press Space or Enter to flip</div></div><div class="study-face study-back"><div class="flashcard-label">${flashcardDirection==='question'?'Answer':'Question'}</div><div class="flashcard-answer">${esc(back)}</div><div class="flip-hint">Click, press Space or Enter to flip</div></div></div><div class="flashcard-actions"><button class="small-button" id="prevCard" aria-label="Previous card">←</button><button class="primary-button" id="flipCard">${flashcardFlipped?'Hide answer':'Reveal answer'}</button><button class="small-button" id="nextCard" aria-label="Next card">→</button><button class="small-button" id="speakCard" title="Read card aloud">🔊</button><button class="small-button ${c.starred?'is-starred':''}" id="starCard" title="${c.starred?'Remove star':'Star card'}">${c.starred?'★':'☆'}</button></div><div class="known-actions"><button class="known-button learning" id="stillLearning">Still learning</button><button class="known-button known" id="knowCard">I know this</button></div><div class="study-shortcuts"><span>← / → navigate</span><span>Space reveal</span><span>S star</span></div></div>`;
    const flip=()=>{flashcardFlipped=!flashcardFlipped;renderFlashcards();};
    $('#studyCard').onclick=flip; $('#studyCard').onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();flip();}};
    $('#flipCard').onclick=flip;
    $('#prevCard').onclick=()=>{flashcardIndex=(flashcardIndex-1+cards.length)%cards.length;flashcardFlipped=false;renderFlashcards();};
    $('#nextCard').onclick=()=>{flashcardIndex=(flashcardIndex+1)%cards.length;flashcardFlipped=false;renderFlashcards();};
    $('#speakCard').onclick=()=>speakText(flashcardFlipped?back:front); $('#starCard').onclick=()=>toggleStar(c);
    $('#stillLearning').onclick=()=>recordCardResult(c,false);
    $('#knowCard').onclick=()=>recordCardResult(c,true);
    $('#flashcardList').innerHTML=cards.slice(0,250).map((c,i)=>`<div class="flashcard-row glass"><div class="flashcard-row-number">${i+1}</div><div class="flashcard-row-main"><strong>${esc(c.question)}</strong><small>${esc(c.deck||'General')}${c.subject?' · '+esc(c.subject):''}</small></div><button class="star-inline ${c.starred?'active':''}" data-card-star="${esc(c.id)}">${c.starred?'★':'☆'}</button><span class="mastery-pill mastery-${Number(progress[c.id]?.mastery||0)}">${Number(progress[c.id]?.mastery||0)>=2?'Mastered':Number(progress[c.id]?.mastery||0)>0?'Learning':'New'}</span><div class="flashcard-row-actions"><button class="small-button" data-card-study="${esc(c.id)}">Study</button><button class="small-button" data-card-edit="${esc(c.id)}">Edit</button><button class="small-button" data-card-delete="${esc(c.id)}">Delete</button></div></div>`).join('');
    document.querySelectorAll('[data-card-study]').forEach(b=>b.onclick=()=>{const i=cards.findIndex(c=>c.id===b.dataset.cardStudy);flashcardIndex=Math.max(0,i);flashcardFlipped=false;renderFlashcards();});
    document.querySelectorAll('[data-card-star]').forEach(b=>b.onclick=()=>{const c=all.find(x=>x.id===b.dataset.cardStar);if(c)toggleStar(c);});
    document.querySelectorAll('[data-card-edit]').forEach(b=>b.onclick=()=>editFlashcard(all.find(x=>x.id===b.dataset.cardEdit)));
    document.querySelectorAll('[data-card-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this flashcard?'))return;const r=await auth('/api/student/flashcards/'+b.dataset.cardDelete,{method:'DELETE'});if(!r.ok){toast('Could not delete card');return;}data.flashcards=data.flashcards.filter(c=>c.id!==b.dataset.cardDelete);renderAll();toast('Flashcard deleted');});
  }
  async function speakText(text){if(!('speechSynthesis' in window)){toast('Speech is not available in this browser.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text||''));u.rate=.9;speechSynthesis.speak(u);}
  async function toggleStar(card){
    const r=await auth('/api/student/flashcards/'+card.id,{method:'PATCH',body:JSON.stringify({starred:!card.starred})});
    if(!r.ok){toast('Could not update star');return;} const updated=await r.json(); const local=data.flashcards.find(c=>c.id===card.id); if(local)local.starred=!!updated.card.starred; renderFlashcards();
  }
  async function recordCardResult(card,correct){
    try{const r=await auth('/api/student/learn/answer',{method:'POST',body:JSON.stringify({card_id:card.id,correct,question_type:'flashcards'})});const j=await r.json().catch(()=>({}));if(r.ok){data=j.student||data;toast(correct?'Marked as known':'Kept in learning');}else toast(j.error||'Could not save progress.');}catch(_){toast('Progress could not be saved.');}
  }
  function editFlashcard(card){
    if(!card)return;
    modal(`<div class="modal-kicker">Edit card</div><h2>Edit flashcard</h2><form id="editFlashcardForm" class="modal-form"><label>Question<textarea id="editQ" rows="3" required>${esc(card.question)}</textarea></label><label>Answer<textarea id="editA" rows="4" required>${esc(card.answer)}</textarea></label><div class="form-row"><label>Deck<input id="editDeck" value="${esc(card.deck||'General')}"></label><label>Subject<input id="editSubject" value="${esc(card.subject||'')}"></label></div><label class="check-row"><input id="editStar" type="checkbox" ${card.starred?'checked':''}> Star this card</label><p id="editError" class="form-error"></p><button class="primary-button" type="submit">Save changes</button></form>`);
    $('#editFlashcardForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button[type=submit]');btn.disabled=true;const r=await auth('/api/student/flashcards/'+card.id,{method:'PATCH',body:JSON.stringify({question:$('#editQ').value,answer:$('#editA').value,deck:$('#editDeck').value,subject:$('#editSubject').value,starred:$('#editStar').checked})});const j=await r.json().catch(()=>({}));if(!r.ok){$('#editError').textContent=j.error||'Could not save this card.';btn.disabled=false;return;}const i=data.flashcards.findIndex(x=>x.id===card.id);if(i>=0)data.flashcards[i]=j.card;closeModal();renderAll();toast('Flashcard updated');};
  }
  function studyCards(){return currentFlashcardBase();}
  function showStudyWorkspace(mode){
    const learn=mode==='learn';
    $('#learnWorkspace').hidden=!learn;
    $('#flashcardStudy').hidden=learn;
    $('#flashcardList').hidden=learn;
    $('.study-tip')?.toggleAttribute('hidden',learn);
    document.querySelectorAll('.study-tab').forEach(b=>b.classList.toggle('active',b.dataset.studyMode===mode));
  }
  function openStudyMode(mode){
    studyMode=mode; go('flashcards');
    if(mode==='flashcards'){showStudyWorkspace('flashcards');renderFlashcards();return;}
    const cards=studyCards(); if(!cards.length){toast('Add some flashcards first.');return;}
    if(mode==='learn'){startLearn();return;}
    showStudyWorkspace('flashcards');
    if(mode==='test')startTest(); else if(mode==='match')startMatch(); else if(mode==='write')startWrite(); else if(mode==='spell')startSpell();
  }
  function startTest(){
    const cards=[...studyCards()].sort(()=>Math.random()-.5); if(!cards.length)return;
    modal(`<div class="study-modal-shell"><div class="study-config"><span class="eyebrow">Test setup</span><h2>Build your practice test</h2><p>Choose the question types and length. Your score stays hidden until you finish.</p><div class="config-grid"><label>Questions<select id="testCount"><option value="5">5</option><option value="10" selected>10</option><option value="20">20</option><option value="all">All cards</option></select></label><label>Time limit<select id="testTimer"><option value="0">No timer</option><option value="60">1 minute</option><option value="180">3 minutes</option><option value="300">5 minutes</option></select></label></div><div class="test-type-grid"><label><input type="checkbox" value="choice" checked> Multiple choice</label><label><input type="checkbox" value="written" checked> Written</label><label><input type="checkbox" value="truefalse" checked> True / False</label><label><input type="checkbox" value="matching"> Matching</label></div><p id="testSetupError" class="form-error"></p><button class="primary-button" id="beginTest">Start test</button></div></div>`);
    $('#beginTest').onclick=()=>{const types=[...document.querySelectorAll('.test-type-grid input:checked')].map(x=>x.value);if(!types.length){$('#testSetupError').textContent='Choose at least one question type.';return;}const n=$('#testCount').value==='all'?cards.length:Math.min(Number($('#testCount').value),cards.length);testState={cards:cards.slice(0,n),idx:0,correct:0,answered:0,locked:false,types,timer:Number($('#testTimer').value),endsAt:0};if(testState.timer)testState.endsAt=Date.now()+testState.timer*1000;startStudyTicker();renderTest();};
  }
  function makeTestType(s,c){return s.types[s.idx%s.types.length]||'choice';}
  function startStudyTicker(){if(studyTicker)clearInterval(studyTicker);studyTicker=setInterval(()=>{if(!testState?.timer)return;const left=Math.max(0,testState.endsAt-Date.now());const el=$('#testClock');if(el)el.textContent=Math.ceil(left/1000)+'s';if(!left){clearInterval(studyTicker);studyTicker=null;testState.idx=testState.cards.length;renderTest();}},250);}
  function renderTest(){
    const s=testState;if(!s)return;if(s.idx>=s.cards.length){const pct=Math.round(s.correct/s.cards.length*100);$('#testShell')?.remove();modal(`<div class="study-modal-shell"><div class="study-result"><div class="result-icon">✓</div><span class="eyebrow">Test complete</span><h2>${s.correct} / ${s.cards.length}</h2><p>${pct}% correct. Review missed cards in Learn or Flashcards.</p><div class="result-actions"><button class="primary-button" id="testAgain">Retake</button><button class="small-button" id="testClose">Done</button></div></div></div>`);$('#testAgain').onclick=startTest;$('#testClose').onclick=closeModal;return;}
    const c=s.cards[s.idx], type=makeTestType(s,c); let body='';
    if(type==='choice'){const others=s.cards.filter(x=>x.id!==c.id).sort(()=>Math.random()-.5).slice(0,3);const opts=[c.answer,...others.map(x=>x.answer)].sort(()=>Math.random()-.5);body=`<div class="test-options">${opts.map(o=>`<button class="test-option" data-test-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div>`;}
    else if(type==='truefalse'){const truth=Math.random()>.5;const shown=truth?c.answer:(s.cards.find(x=>x.id!==c.id)?.answer||c.answer);body=`<div class="test-statement"><strong>${esc(shown)}</strong><p>Is this the correct answer for the question above?</p></div><div class="test-options tf"><button class="test-option" data-test-tf="true">True</button><button class="test-option" data-test-tf="false">False</button></div>`;s.currentTruth=truth;}
    else if(type==='matching'){const pair=[c,...s.cards.filter(x=>x.id!==c.id).slice(0,3)];const opts=[...pair].sort(()=>Math.random()-.5);body=`<div class="test-statement"><p>Choose the definition that matches the question.</p></div><div class="test-options">${opts.map(o=>`<button class="test-option" data-test-answer="${esc(o.answer)}">${esc(o.answer)}</button>`).join('')}</div>`;}
    else body=`<form id="testWrittenForm" class="written-test"><input id="testWritten" autocomplete="off" placeholder="Type your answer…"><button class="primary-button" type="submit">Check</button></form>`;
    $('#modalContent').innerHTML=`<div class="study-modal-shell" id="testShell"><div class="test-header"><div><span class="eyebrow">Test · ${type==='choice'?'Multiple choice':type==='truefalse'?'True / False':type==='matching'?'Matching':'Written'}</span><h2>Check your recall</h2></div><span>${s.idx+1} / ${s.cards.length}</span></div><div class="test-progress"><i style="width:${s.idx/s.cards.length*100}%"></i></div><div class="test-question">${esc(c.question)}</div>${body}<div class="test-footer"><span>${s.timer?`Time left: <b id="testClock">${Math.max(0,Math.ceil((s.endsAt-Date.now())/1000))}s</b>`:'Untimed'}</span><button class="text-button" id="testExit">Exit</button></div></div>`;
    if(type==='choice'||type==='matching')document.querySelectorAll('[data-test-answer]').forEach(b=>b.onclick=()=>answerTest(b.dataset.testAnswer===c.answer,b));
    if(type==='truefalse')document.querySelectorAll('[data-test-tf]').forEach(b=>b.onclick=()=>answerTest(b.dataset.testTf===String(s.currentTruth),b));
    if(type==='written'){$('#testWrittenForm').onsubmit=e=>{e.preventDefault();answerTest(answerMatches($('#testWritten').value,c.answer),$('#testWrittenForm button'));};setTimeout(()=>$('#testWritten')?.focus(),0);}
    $('#testExit').onclick=closeModal;
  }
  function answerTest(ok,button){const s=testState;if(!s||s.locked)return;s.locked=true;if(button)button.classList.add(ok?'correct':'wrong');if(ok)s.correct++;s.answered++;const c=s.cards[s.idx];recordCardResult(c,ok).finally(()=>setTimeout(()=>{s.idx++;s.locked=false;renderTest();},600));}
  function startWrite(){const cards=[...studyCards()].sort(()=>Math.random()-.5);modal('<div class="study-modal-shell" id="writeShell"></div>');testState={cards,idx:0,correct:0,answered:0,locked:false};renderWrite();}
  function renderWrite(){const s=testState;if(s.idx>=s.cards.length){renderStudyResult('Write complete',s.correct,s.cards.length,startWrite);return;}const c=s.cards[s.idx];$('#writeShell').innerHTML=`<div class="test-header"><div><span class="eyebrow">Write</span><h2>Type the answer</h2></div><span>${s.idx+1} / ${s.cards.length}</span></div><div class="test-progress"><i style="width:${s.idx/s.cards.length*100}%"></i></div><div class="test-question">${esc(c.question)}</div><form id="writeForm" class="written-test"><input id="writeInput" autocomplete="off" placeholder="Type what you remember…"><button class="primary-button">Check answer</button></form><div class="test-footer"><span>Active recall · auto-graded</span><button class="text-button" id="writeExit">Exit</button></div>`;$('#writeForm').onsubmit=e=>{e.preventDefault();if(s.locked)return;s.locked=true;const ok=answerMatches($('#writeInput').value,c.answer);if(ok)s.correct++;s.answered++;recordCardResult(c,ok).finally(()=>setTimeout(()=>{s.idx++;s.locked=false;renderWrite();},650));};$('#writeExit').onclick=closeModal;setTimeout(()=>$('#writeInput')?.focus(),0);}
  function startSpell(){const cards=[...studyCards()].sort(()=>Math.random()-.5);modal('<div class="study-modal-shell" id="spellShell"></div>');testState={cards,idx:0,correct:0,answered:0,locked:false};renderSpell();}
  function renderSpell(){const s=testState;if(s.idx>=s.cards.length){renderStudyResult('Spell complete',s.correct,s.cards.length,startSpell);return;}const c=s.cards[s.idx];$('#spellShell').innerHTML=`<div class="test-header"><div><span class="eyebrow">Spell</span><h2>Listen and type</h2></div><span>${s.idx+1} / ${s.cards.length}</span></div><div class="spell-listen"><button class="primary-button" id="speakSpell">🔊 Play audio</button><p>Type the term you hear.</p></div><form id="spellForm" class="written-test"><input id="spellInput" autocomplete="off" placeholder="Type what you hear…"><button class="primary-button">Check</button></form><div class="test-footer"><span>Speech uses your browser's voice</span><button class="text-button" id="spellExit">Exit</button></div>`;const speak=()=>{if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(c.question);u.rate=.88;speechSynthesis.speak(u);}else toast('Speech is not available in this browser.');};$('#speakSpell').onclick=speak;$('#spellForm').onsubmit=e=>{e.preventDefault();if(s.locked)return;s.locked=true;const ok=answerMatches($('#spellInput').value,c.question);if(ok)s.correct++;s.answered++;recordCardResult(c,ok).finally(()=>setTimeout(()=>{s.idx++;s.locked=false;renderSpell();},650));};$('#spellExit').onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();closeModal();};setTimeout(()=>{speak();$('#spellInput')?.focus();},250);}
  function renderStudyResult(title,correct,total,again){const pct=total?Math.round(correct/total*100):0;$('#modalContent').innerHTML=`<div class="study-modal-shell"><div class="study-result"><div class="result-icon">✓</div><span class="eyebrow">${title}</span><h2>${correct} / ${total}</h2><p>${pct}% correct.</p><div class="result-actions"><button class="primary-button" id="studyAgain">Again</button><button class="small-button" id="studyDone">Done</button></div></div></div>`;$('#studyAgain').onclick=again;$('#studyDone').onclick=closeModal;}
  function startMatch(){const source=[...studyCards()].sort(()=>Math.random()-.5).slice(0,Math.min(6,studyCards().length));const tiles=[...source.map(c=>({id:c.id,type:'term',text:c.question})),...source.map(c=>({id:c.id,type:'answer',text:c.answer}))].sort(()=>Math.random()-.5);matchState={tiles,selected:null,matches:0,moves:0,started:Date.now(),wrong:[]};modal('<div class="study-modal-shell" id="matchShell"></div>');renderMatch();}
  function renderMatch(){const s=matchState;if(!s)return;if(s.matches*2===s.tiles.length){const sec=Math.max(1,Math.round((Date.now()-s.started)/1000));$('#matchShell').innerHTML=`<div class="study-result"><div class="result-icon">✦</div><span class="eyebrow">Match complete</span><h2>${s.moves} moves</h2><p>You matched ${s.matches} pairs in ${sec}s.</p><div class="result-actions"><button class="primary-button" id="matchAgain">Play again</button><button class="small-button" id="matchClose">Done</button></div></div>`;$('#matchAgain').onclick=startMatch;$('#matchClose').onclick=closeModal;return;}$('#matchShell').innerHTML=`<div class="test-header"><div><span class="eyebrow">Match</span><h2>Find the pairs</h2></div><span>${s.matches} / ${s.tiles.length/2}</span></div><div class="match-timer">${Math.floor((Date.now()-s.started)/1000)}s</div><div class="match-grid">${s.tiles.map((t,i)=>`<button class="match-tile ${t.matched?'matched':''} ${s.selected===i?'selected':''} ${s.wrong?.includes(i)?'wrong':''}" data-match="${i}" ${t.matched?'disabled':''}>${esc(t.text)}</button>`).join('')}</div><div class="test-footer"><span>Moves: ${s.moves}</span><button class="text-button" id="matchExit">Exit</button></div>`;document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.match);if(s.tiles[i].matched||s.selected===i)return;if(s.selected===null){s.selected=i;renderMatch();return;}s.moves++;const a=s.tiles[s.selected],bb=s.tiles[i];if(a.id===bb.id&&a.type!==bb.type){a.matched=bb.matched=true;s.matches++;s.selected=null;recordCardResult(data.flashcards.find(c=>c.id===a.id),true);renderMatch();}else{const first=s.selected;s.wrong=[first,i];s.selected=null;renderMatch();setTimeout(()=>{s.wrong=[];renderMatch();},420);}});$('#matchExit').onclick=closeModal;}

  let learnGoal=10, learnSession=null;
  function learnStats(){
    const cards=learnCards(), progress=data.learn_progress||{};
    let mastered=0,familiar=0,newCards=0;
    cards.forEach(c=>{const m=Number(progress[c.id]?.mastery||0);if(m>=2)mastered++;else if(m===1)familiar++;else newCards++;});
    const pct=cards.length?Math.round(mastered/cards.length*100):0;
    if($('#learnNew'))$('#learnNew').textContent=newCards;
    if($('#learnFamiliar'))$('#learnFamiliar').textContent=familiar;
    if($('#learnMastered'))$('#learnMastered').textContent=mastered;
    if($('#learnPercent'))$('#learnPercent').textContent=pct+'%';
    if($('#learnRing'))$('#learnRing').style.setProperty('--learn-pct',pct+'%');
    const filter=$('#learnDeckFilter');
    if(filter){const sets=(data.flashcard_sets||[]).filter(x=>x&&x.name);const old=filter.value||flashcardDeck||'all';filter.innerHTML='<option value="all">All sets</option>'+sets.map(d=>`<option value="${esc(d.name)}">${esc(d.name)}</option>`).join('');filter.value=sets.some(x=>x.name===old)?old:'all';}
  }
  function learnCards(){const deck=$('#learnDeckFilter')?.value||flashcardDeck||'all';return(data.flashcards||[]).filter(c=>deck==='all'||(c.deck||'General')===deck);}
  function answerMatches(input,answer){
    const norm=x=>String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
    const a=norm(answer),b=norm(input);if(!a||!b)return false;if(a===b)return true;
    const tokens=a.split(' ').filter(Boolean),bt=new Set(b.split(' ').filter(Boolean));
    const overlap=tokens.filter(x=>bt.has(x)).length/Math.max(tokens.length,1);
    return overlap>=.9&&b.length>=Math.min(6,a.length*.65);
  }
  function startLearn(){
    go('flashcards');showStudyWorkspace('learn');
    const source=learnCards();
    if(!source.length){toast('Add or import some flashcards first.');showStudyWorkspace('flashcards');return;}
    const mastered=new Set(source.filter(c=>Number(data.learn_progress?.[c.id]?.mastery||0)>=2).map(c=>c.id));
    const active=source.filter(c=>!mastered.has(c.id));
    if(!active.length){finishLearn(true);return;}
    learnSession={
      source,active,round:1,phase:'choice',index:0,correct:0,answered:0,
      roundCorrect:0,roundWrong:[],wrongThisRound:[],locked:false,choiceLocked:false,
      startedAt:Date.now(),goal:active.length,totalTarget:active.length*2
    };
    renderLearnQuestion();
  }
  function finishLearn(alreadyMastered=false){
    const s=learnSession;if(!s)return;
    const score=s.answered?Math.round(s.correct/s.answered*100):100;
    const completed=s.active?.length||0;
    $('#learnCard').innerHTML=`<div class="learn-start learn-complete"><div class="learn-symbol">✓</div><span class="learn-checkpoint-kicker">Learning complete</span><h2>${alreadyMastered?'You already know this set':'You nailed the round'}</h2><p>${alreadyMastered?'All selected cards are already mastered.':'Every card in this session has now been recalled by typing.'}</p><div class="learn-result-grid"><div><strong>${score}%</strong><span>accuracy</span></div><div><strong>${s.round}</strong><span>round${s.round===1?'':'s'}</span></div><div><strong>${completed}</strong><span>cards</span></div></div><div class="result-actions"><button class="primary-button" id="learnAgain">Study again</button><button class="small-button" id="learnBackCards">Back to flashcards</button></div></div>`;
    $('#learnAgain').onclick=startLearn;$('#learnBackCards').onclick=()=>{showStudyWorkspace('flashcards');renderFlashcards();};learnStats();
  }
  function learnCheckpoint(){
    const s=learnSession;
    const wrong=s.wrongThisRound.slice();
    if(!wrong.length){finishLearn();return;}
    s.round++;s.active=wrong;s.index=0;s.phase='choice';s.roundCorrect=0;s.wrongThisRound=[];s.locked=false;
    $('#learnCard').innerHTML=`<div class="learn-start learn-checkpoint"><div class="checkpoint-mark">↻</div><span class="learn-checkpoint-kicker">Round ${s.round-1} complete</span><h2>Checkpoint</h2><p><strong>${wrong.length}</strong> card${wrong.length===1?' needs':'s need'} another pass. Each card will go through multiple choice again, then you’ll type the answer again.</p><div class="checkpoint-summary"><span><b>${s.active.length}</b> remaining</span><span><b>${s.round-1}</b> round${s.round-1===1?'':'s'} completed</span></div><button class="primary-button" id="continueLearnRound">Start round ${s.round}</button></div>`;
    $('#continueLearnRound').onclick=renderLearnQuestion;learnStats();
  }
  function renderLearnQuestion(){
    const s=learnSession;if(!s||!s.active.length){finishLearn();return;}
    if(s.index>=s.active.length){learnCheckpoint();return;}
    const c=s.active[s.index], total=s.active.length, progress=Math.round(((s.round-1)*total+s.index)/(Math.max(1,total*s.round))*100);
    const isChoice=s.phase==='choice';
    let body='';
    if(isChoice){
      const pool=s.active.filter(x=>x.id!==c.id);
      const distractors=[];
      for(const x of pool){if(!distractors.some(y=>y.answer===x.answer))distractors.push(x);if(distractors.length===3)break;}
      const options=[c,...distractors].map(x=>x.answer);
      while(options.length<Math.min(4,s.active.length))options.push(c.answer);
      const unique=[...new Set(options)].slice(0,4).sort((a,b)=>String(a).localeCompare(String(b)));
      body=`<div class="learn-options">${unique.map(o=>`<button class="learn-option" data-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div>`;
    }else{
      body=`<form id="learnAnswerForm" class="learn-type-form"><input class="learn-input" id="learnInput" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Type the answer from memory…"><button class="primary-button" type="submit">Check answer</button></form>`;
    }
    $('#learnCard').innerHTML=`<div class="learn-question">
      <div class="learn-meta"><span>Round ${s.round} · ${isChoice?'Multiple choice':'Type the answer'}</span><span>${s.index+1} / ${total}</span></div>
      <div class="learn-progressbar"><i style="width:${Math.min(100,progress)}%"></i></div>
      <div class="learn-round-label">${isChoice?'Recognise it first':'Now retrieve it yourself'}</div>
      <div class="learn-prompt">${esc(c.question)}</div>${body}
      <div id="learnFeedback" class="learn-feedback" hidden></div>
      <div class="learn-flow-note">${isChoice?'After this choice, you must type the answer for the same card.':'A correct typed answer clears this card. A miss brings it back in the next round.'}</div>
    </div>`;
    if(isChoice)document.querySelectorAll('.learn-option').forEach(b=>b.onclick=()=>submitLearnChoice(b,c));
    else {$('#learnAnswerForm').onsubmit=e=>{e.preventDefault();submitLearnTyped($('#learnInput').value,c);};setTimeout(()=>$('#learnInput')?.focus(),0);}
  }
  function submitLearnChoice(button,card){
    const s=learnSession;if(!s||s.locked)return;s.locked=true;
    const ok=answerMatches(button.dataset.answer,card.answer);button.classList.add(ok?'correct':'wrong');
    document.querySelectorAll('.learn-option').forEach(x=>x.disabled=true);
    s.choiceResult=ok;
    const feedback=$('#learnFeedback');if(feedback){feedback.hidden=false;feedback.innerHTML=ok?'<strong>Correct.</strong> Now type the answer from memory.':'<strong>Not quite.</strong> You still need to type the correct answer next.';}
    setTimeout(()=>{s.phase='typed';s.locked=false;renderLearnQuestion();},520);
  }
  async function submitLearnTyped(given,card){
    const s=learnSession;if(!s||s.locked)return;s.locked=true;
    const correct=answerMatches(given,card.answer);const feedback=$('#learnFeedback');
    if(feedback){feedback.hidden=false;feedback.innerHTML=correct?'<strong>Correct.</strong> This card has passed the typed recall.':`<strong>Keep practising.</strong><br><span>Correct answer: ${esc(card.answer)}</span>`;}
    try{
      const r=await auth('/api/student/learn/answer',{method:'POST',body:JSON.stringify({card_id:card.id,correct,question_type:'written',round:s.round})});
      const j=await r.json().catch(()=>({}));if(r.ok)data=j.student||data;else toast(j.error||'Could not save Learn progress.');
    }catch(_){toast('Progress could not be saved.');}
    s.answered++;if(correct){s.correct++;s.roundCorrect++;}else{s.wrongThisRound.push(card);}
    setTimeout(()=>{s.index++;s.phase='choice';s.locked=false;if(s.index>=s.active.length)learnCheckpoint();else renderLearnQuestion();},700);
  }
  function initLearn(){
    learnStats();
    document.querySelectorAll('.goal').forEach(b=>b.onclick=()=>{document.querySelectorAll('.goal').forEach(x=>x.classList.remove('active'));b.classList.add('active');learnGoal=Number(b.dataset.goal);});
    $('#learnStartHero').onclick=startLearn;
    $('#learnExitBtn').onclick=()=>{showStudyWorkspace('flashcards');renderFlashcards();};
    $('#learnDeckFilter').onchange=()=>{flashcardDeck=$('#learnDeckFilter').value||'all';learnStats();};
  }
  function openFlashcardOptions(){modal(`<div class="modal-kicker">Flashcards</div><h2>Study options</h2><div class="study-option-list"><label>Show first<select id="flashDirection"><option value="question" ${flashcardDirection==='question'?'selected':''}>Question</option><option value="answer" ${flashcardDirection==='answer'?'selected':''}>Answer</option></select></label><label>Play speed<select id="flashSpeed"><option value="2">2 seconds</option><option value="4" ${flashcardAutoSeconds===4?'selected':''}>4 seconds</option><option value="6" ${flashcardAutoSeconds===6?'selected':''}>6 seconds</option><option value="8" ${flashcardAutoSeconds===8?'selected':''}>8 seconds</option></select></label><label class="check-row"><input id="flashSpeak" type="checkbox" ${flashSpeak?'checked':''}> Read cards aloud during Play</label></div><div class="result-actions"><button class="primary-button" id="saveFlashOptions">Save options</button></div>`);$('#saveFlashOptions').onclick=()=>{flashcardDirection=$('#flashDirection').value;flashcardAutoSeconds=Number($('#flashSpeed').value);flashSpeak=$('#flashSpeak').checked;closeModal();renderFlashcards();};}
  function toggleFlashcardPlay(){if(flashcardAutoplay){clearInterval(flashcardAutoplay);flashcardAutoplay=null;$('#playFlashcards').textContent='▶ Play';return;}const cards=currentFlashcardBase();if(!cards.length)return;flashcardFlipped=false;renderFlashcards();flashcardAutoplay=setInterval(()=>{const current=currentFlashcardBase();if(!current.length){clearInterval(flashcardAutoplay);flashcardAutoplay=null;return;}if(!flashcardFlipped){flashcardFlipped=true;renderFlashcards();if(flashSpeak)speakText(current[flashcardIndex]?.answer);}else{flashcardIndex=(flashcardIndex+1)%current.length;flashcardFlipped=false;renderFlashcards();if(flashSpeak)speakText(current[flashcardIndex]?.question);}},flashcardAutoSeconds*1000);$('#playFlashcards').textContent='❚❚ Pause';}
  function newFlashcardSet(){modal(`<div class="modal-kicker">Study set</div><h2>Create a set</h2><p class="modal-subtitle">Sets are saved to your account, including empty sets.</p><form id="setForm" class="modal-form"><label>Name<input id="setName" maxlength="80" required placeholder="e.g. Biology — Cells"></label><label>Subject<input id="setSubject" maxlength="80" placeholder="Optional"></label><label>Description<textarea id="setDescription" maxlength="240" rows="3" placeholder="What are you learning in this set?"></textarea></label><p id="setError" class="form-error"></p><button class="primary-button" type="submit">Create set</button></form>`);$('#setForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;const r=await auth('/api/student/flashcard-sets',{method:'POST',body:JSON.stringify({name:$('#setName').value,subject:$('#setSubject').value,description:$('#setDescription').value})});const j=await r.json().catch(()=>({}));if(!r.ok){$('#setError').textContent=j.error||'Could not create the set.';btn.disabled=false;return;}data=j.student||data;flashcardDeck=j.set.name;flashcardIndex=0;flashcardFlipped=false;closeModal();renderAll();toast('Study set created');};setTimeout(()=>$('#setName')?.focus(),0);}
  function manageFlashcardSet(){const sets=data.flashcard_sets||[], current=sets.find(x=>x.name===flashcardDeck)||sets[0];if(!current){newFlashcardSet();return;}modal(`<div class="modal-kicker">Study set</div><h2>Set options</h2><form id="setEditForm" class="modal-form"><label>Name<input id="setEditName" maxlength="80" required value="${esc(current.name)}"></label><label>Subject<input id="setEditSubject" maxlength="80" value="${esc(current.subject||'')}"></label><label>Description<textarea id="setEditDescription" maxlength="240" rows="3">${esc(current.description||'')}</textarea></label><p id="setEditError" class="form-error"></p><div class="result-actions"><button class="primary-button" type="submit">Save changes</button><button class="small-button" type="button" id="deleteSetBtn">Delete set</button></div></form>`);$('#setEditForm').onsubmit=async e=>{e.preventDefault();const r=await auth('/api/student/flashcard-sets/'+current.id,{method:'PATCH',body:JSON.stringify({name:$('#setEditName').value,subject:$('#setEditSubject').value,description:$('#setEditDescription').value})});const j=await r.json().catch(()=>({}));if(!r.ok){$('#setEditError').textContent=j.error||'Could not save the set.';return;}data=j.student||data;flashcardDeck=j.set.name;closeModal();renderAll();toast('Set updated');};$('#deleteSetBtn').onclick=async()=>{if(!confirm('Delete this empty set? Cards must be moved or deleted first.'))return;const r=await auth('/api/student/flashcard-sets/'+current.id,{method:'DELETE'});const j=await r.json().catch(()=>({}));if(!r.ok){$('#setEditError').textContent=j.error||'Could not delete the set.';return;}data=j.student||data;flashcardDeck='all';closeModal();renderAll();toast('Set deleted');};}
  function addFlashcard(){modal(`<div class="modal-kicker">Active recall</div><h2>New flashcard</h2><form id="flashcardForm" class="modal-form"><label>Question<textarea id="fcQuestion" rows="3" required placeholder="What is…?"></textarea></label><label>Answer<textarea id="fcAnswer" rows="4" required placeholder="The answer…"></textarea></label><div class="form-row"><label>Deck<input id="fcDeck" value="General"></label><label>Subject<input id="fcSubject" placeholder="Optional"></label></div><label class="check-row"><input id="fcStar" type="checkbox"> Star this card</label><p id="fcError" class="form-error"></p><button class="primary-button" type="submit">Add flashcard</button></form>`);$('#flashcardForm').onsubmit=async e=>{e.preventDefault();const q=$('#fcQuestion').value.trim(),a=$('#fcAnswer').value.trim();if(!q||!a){$('#fcError').textContent='Question and answer are required.';return;}const r=await auth('/api/student/flashcards/import',{method:'POST',body:JSON.stringify({text:`${q}\t${a}`,deck:$('#fcDeck').value.trim()||'General',subject:$('#fcSubject').value.trim(),format:'txt'})});const j=await r.json().catch(()=>({}));if(!r.ok){$('#fcError').textContent=j.error||'Could not add flashcard.';return;}const added=j.flashcards?.[0];if(added?.id&&$('#fcStar').checked){await auth('/api/student/flashcards/'+added.id,{method:'PATCH',body:JSON.stringify({starred:true})});}data=j.student||data;closeModal();renderAll();toast('Flashcard added');};setTimeout(()=>$('#fcQuestion')?.focus(),0);}
  function importFlashcards(){modal(`<div class="modal-kicker">Import</div><h2>Bring in your cards</h2><p class="modal-subtitle">Upload a CSV/TXT file or paste your cards. Rian accepts question/answer pairs separated by commas, tabs, <code>::</code> or <code>|</code>.</p><form id="importForm" class="modal-form"><label>Deck<input id="importDeck" value="General" maxlength="80"></label><label>Subject<input id="importSubject" placeholder="Optional" maxlength="80"></label><label>File <input id="importFile" type="file" accept=".csv,.txt,text/csv,text/plain"></label><label>Or paste cards<textarea id="importText" rows="10" placeholder="Question,Answer\nWhat is ATP?,The cell's energy currency\n\nOr: question :: answer"></textarea></label><p class="flashcard-import-help">Up to 1,000 cards per import. Duplicates are skipped automatically.</p><p id="importError" class="form-error"></p><button class="primary-button" type="submit">Import cards</button></form>`);$('#importFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{$('#importText').value=await file.text();$('#importText').focus();toast(`${file.name} ready to import`);}catch(_){$('#importError').textContent='We could not read that file.';}};$('#importForm').onsubmit=async e=>{e.preventDefault();const btn=$('#importForm button[type=submit]'),error=$('#importError');error.textContent='';const raw=$('#importText').value.trim();if(!raw){error.textContent='Choose a CSV/TXT file or paste some cards first.';return;}btn.disabled=true;btn.textContent='Importing…';try{const r=await auth('/api/student/flashcards/import',{method:'POST',body:JSON.stringify({text:raw,deck:$('#importDeck').value,subject:$('#importSubject').value,format:'auto'})});const j=await r.json().catch(()=>({}));if(!r.ok){error.textContent=j.error||'Import failed.';return;}data=j.student||data;flashcardDeck='all';flashcardIndex=0;renderAll();closeModal();toast(`${j.added} card${j.added===1?'':'s'} imported${j.duplicates?` · ${j.duplicates} duplicate${j.duplicates===1?'':'s'} skipped`:''}`);}catch(_){error.textContent='Could not reach the hub.';}finally{btn.disabled=false;btn.textContent='Import cards';}};setTimeout(()=>$('#importText')?.focus(),0);}
  function renderAll(){refreshToday();renderProfile();renderStats();renderHome();renderTimetable();renderTasks();renderSubjects();renderFlashcards();learnStats();}
  function go(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={home:'Overview',timetable:'Schedule',tasks:'Planning',revision:'Learning',flashcards:'Active recall',assistant:'Study assistant',settings:'Personalise'};$('#pageKicker').textContent=titles[view]||'STUDENT HUB';window.scrollTo({top:0,behavior:'smooth'});}
  function modal(html){$('#modalContent').innerHTML=html;$('#modal').hidden=false;}
  function closeModal(){if(studyTicker){clearInterval(studyTicker);studyTicker=null;}$('#modal').hidden=true;}
  function addTask(){modal(`<div class="modal-kicker">New task</div><h2>Add a task</h2><form id="taskForm" class="modal-form"><label>Task title<input id="mTaskTitle" required placeholder="e.g. Finish Biology worksheet"></label><div class="form-row"><label>Subject<input id="mTaskSubject" placeholder="Biology"></label><label>Due date<input id="mTaskDue" type="date"></label></div><label>Priority<select id="mTaskPriority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></label><button class="primary-button" type="submit">Add task</button></form>`);$('#taskForm').onsubmit=async e=>{e.preventDefault();const r=await auth('/api/student/tasks',{method:'POST',body:JSON.stringify({title:$('#mTaskTitle').value,subject:$('#mTaskSubject').value,due:$('#mTaskDue').value,priority:$('#mTaskPriority').value})});if(!r.ok){toast('Could not add task');return;}data.tasks.push((await r.json()).task);closeModal();renderAll();toast('Task added');};}
  function addLesson(){modal(`<div class="modal-kicker">Timetable</div><h2>Add a lesson</h2><form id="lessonForm" class="modal-form"><div class="form-row"><label>Day<select id="mDay">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map(d=>`<option value="${d.toLowerCase()}">${d}</option>`).join('')}</select></label><label>Subject<input id="mSubject" required placeholder="Maths"></label></div><div class="form-row"><label>Start<input id="mStart" type="time" required></label><label>End<input id="mEnd" type="time" required></label></div><label>Room / teacher<input id="mRoom" placeholder="M2 · Ms Smith"></label><button class="primary-button" type="submit">Add lesson</button></form>`);$('#lessonForm').onsubmit=async e=>{e.preventDefault();data.timetable.push({id:crypto.randomUUID(),day:$('#mDay').value,subject:$('#mSubject').value,start:$('#mStart').value,end:$('#mEnd').value,room:$('#mRoom').value});await save();closeModal();renderAll();toast('Lesson added');};}
  function addSubject(){
    go('settings');
    modal(`<div class="modal-kicker">New course</div><h2>Add a course</h2><p class="modal-subtitle">Set the basics now. You can edit the course later from Settings.</p><form id="courseForm" class="modal-form">
      <label>Subject <input id="mCourseName" required maxlength=120 placeholder="e.g. Biology" autocomplete="off"></label>
      <div class="form-row"><label>Course / qualification <input id="mCourseType" maxlength=120 placeholder="e.g. GCSE Biology"></label><label>Exam board <select id="mCourseBoard"><option value="">Select board</option>${boards.map(b=>`<option value="${esc(b)}">${esc(b)}</option>`).join('')}</select></label></div>
      <label>Specification link <input id="mCourseSpec" type="url" placeholder="https://…" autocomplete="url"><small class="field-help">Optional. Use the official specification page or PDF.</small></label>
      <label>Course progress <div class="progress-input"><input id="mCourseProgress" type="range" min="0" max="100" step="5" value="0"><output id="mCourseProgressOut">0%</output></div></label>
      <p id="courseFormError" class="form-error" role="alert"></p><button class="primary-button" type="submit">Add course</button>
    </form>`);
    const progress=$('#mCourseProgress'), output=$('#mCourseProgressOut');
    progress.oninput=()=>output.value=progress.value+'%';
    $('#courseForm').onsubmit=async e=>{
      e.preventDefault();
      const error=$('#courseFormError'); error.textContent='';
      const name=$('#mCourseName').value.trim(), course=$('#mCourseType').value.trim(), board=$('#mCourseBoard').value, specification=$('#mCourseSpec').value.trim();
      if(!name){error.textContent='Enter a subject name.';$('#mCourseName').focus();return;}
      if(specification && !/^https?:\/\//i.test(specification)){error.textContent='The specification link must start with http:// or https://.';$('#mCourseSpec').focus();return;}
      const submit=$('#courseForm button[type=submit]'); submit.disabled=true; submit.textContent='Adding…';
      try{
        const r=await auth('/api/student/courses',{method:'POST',body:JSON.stringify({name,course,exam_board:board,specification,progress:Number(progress.value)})});
        const j=await r.json().catch(()=>({}));
        if(!r.ok){error.textContent=j.error||'Could not add this course.';return;}
        data=j.student||data; closeModal(); renderAll(); toast(`${name} added to your courses`);
      }catch(err){error.textContent='Could not reach the hub. Check your connection and try again.';}
      finally{submit.disabled=false;submit.textContent='Add course';}
    };
    setTimeout(()=>$('#mCourseName')?.focus(),0);
  }
  async function settings(){ const courseRows=[...document.querySelectorAll('.course-editor-row')]; data.subjects=courseRows.map(row=>{const get=k=>row.querySelector(`[data-field=\"${k}\"]`)?.value?.trim()||'';return {name:get('name'),course:get('course'),exam_board:get('exam_board'),specification:get('specification'),progress:Number(row.querySelector('[data-field=progress]')?.value||0)};}).filter(x=>x.name); const linkRows=[...document.querySelectorAll('.editor-row')]; data.quick_links=linkRows.map((row,i)=>({title:row.querySelector('[data-link=title]')?.value?.trim()||'',url:row.querySelector('[data-link=url]')?.value?.trim()||'',icon:(row.querySelector('[data-link=title]')?.value?.trim()||'↗').charAt(0).toUpperCase()})).filter(x=>x.title&&x.url); data.profile={...(data.profile||{}),display_name:$('#settingName').value.trim(),year_group:$('#settingYear').value.trim(),school:$('#settingSchool').value.trim()}; if(await save()){renderAll();$('#settingsMessage').textContent='Saved successfully.';setTimeout(()=>$('#settingsMessage').textContent='',2200);toast('Settings saved');}}
  function init(){document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#addTaskBtn').onclick=addTask;$('#addLessonBtn').onclick=addLesson;$('#addSubjectBtn').onclick=addSubject;$('#addCourse').onclick=addSubject;$('#newFlashcardBtn').onclick=addFlashcard;$('#newFlashcardSetBtn').onclick=newFlashcardSet;$('#importFlashcardsBtn').onclick=importFlashcards;$('#manageFlashcardSet').onclick=manageFlashcardSet;document.querySelectorAll('.study-tab').forEach(b=>b.onclick=()=>openStudyMode(b.dataset.studyMode));initLearn();$('#flashcardStarredFilter').onclick=()=>{flashcardStarredOnly=!flashcardStarredOnly;flashcardIndex=0;flashcardFlipped=false;renderFlashcards();};$('#flashcardOptions').onclick=openFlashcardOptions;$('#playFlashcards').onclick=toggleFlashcardPlay;$('#shuffleFlashcards').onclick=()=>{const cards=data.flashcards||[];if(cards.length){flashcardDeck=$('#flashcardDeckFilter')?.value||'all';const filtered=cards.filter(c=>flashcardDeck==='all'||(c.deck||'General')===flashcardDeck);flashcardIndex=filtered.length?Math.floor(Math.random()*filtered.length):0;flashcardFlipped=false;renderFlashcards();}};$('#flashcardDeckFilter').onchange=e=>{flashcardDeck=e.target.value;flashcardIndex=0;flashcardFlipped=false;renderFlashcards();};document.addEventListener('keydown',e=>{if(document.querySelector('#view-flashcards.active')&&!document.querySelector('#modal:not([hidden])')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){const cards=studyCards();if(e.key==='ArrowLeft'&&cards.length){flashcardIndex=(flashcardIndex-1+cards.length)%cards.length;flashcardFlipped=false;renderFlashcards();}if(e.key==='ArrowRight'&&cards.length){flashcardIndex=(flashcardIndex+1)%cards.length;flashcardFlipped=false;renderFlashcards();}if(e.key===' '&&cards.length){e.preventDefault();flashcardFlipped=!flashcardFlipped;renderFlashcards();}if((e.key==='s'||e.key==='S')&&cards.length){e.preventDefault();const c=cards[flashcardIndex];if(c)toggleStar(c);}}});$('#addQuickLink').onclick=()=>{data.quick_links.push({title:'',url:'',icon:'↗'});renderQuickLinkEditor();setTimeout(()=>document.querySelector('#quickLinkEditor .editor-row:last-child input')?.focus(),0);};$('#saveSettings').onclick=settings;$('#modalClose').onclick=closeModal;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#refreshHub').onclick=load;document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{taskFilter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderTasks();});let focusTimer=null,focusEndsAt=0;$('#focusBtn').onclick=()=>{if(focusTimer){clearInterval(focusTimer);focusTimer=null;$('#focusBtn').textContent='Start 25 min →';$('#statFocus').textContent='Ready';toast('Focus session stopped');return;}focusEndsAt=Date.now()+25*60*1000;const tick=()=>{const left=Math.max(0,focusEndsAt-Date.now()),mins=Math.floor(left/60000),secs=Math.floor((left%60000)/1000);$('#statFocus').textContent=`${mins}:${String(secs).padStart(2,'0')}`;$('#focusBtn').textContent=left?'Stop focus →':'Start 25 min →';if(!left){clearInterval(focusTimer);focusTimer=null;toast('Focus session complete');$('#statFocus').textContent='Ready';}};tick();focusTimer=setInterval(tick,1000);toast('Focus session started');};if(document.body.classList.contains('logged-in'))load();}
  const reset=()=>{data={profile:{},tasks:[],timetable:[],subjects:[],quick_links:[],flashcards:[],flashcard_sets:[]};renderAll();};
  return {init,load,go,reset};
})();
document.addEventListener('DOMContentLoaded',()=>Hub.init());
